uw_auto_h3_0237: "2. Optimized Solo Attack Formations & Examples",

uw_auto_p_0238: "Step 1: Equipment Filter (Select Solo-Active Heroes)",
uw_auto_p_0239: "Bomber Slot → Worrell (+16% ATK), Alph (+16% ATK), or Koschevoi (+16% DEF)",
uw_auto_p_0240: "Shooter Slot → Veronica (+16% Lethality) or Edwin (+16% HP)",
uw_auto_p_0241: "Shield Slot → Best Mechanical Complement (e.g., Caesar, Otto, Tyronn)",
uw_auto_p_0242: "Step 2: Skill Synergy Match vs. Scout Report",

uw_auto_h4_0243: "FORMATION 1: The First-Strike Tactical Executioner",
uw_auto_p_0244: "High raw damage, instant turn-1 stat suppression, and multi-hit basic attack combos.",
uw_auto_li_0245: "Bomber Choice: Worrell (Equipment: +16% ATK active in Solo Combat). Skills grant +25% Basic Attack DMG and a 50% Combo chance for Bombers.",
uw_auto_li_0246: "Shooter Choice: Edwin (Equipment: +16% HP active in Solo Attack). Skills grant +20% Shieldbearer / +30% Shooter damage reduction and turn-3 Tactical bursts.",
uw_auto_li_0247: "Shield Choice: Caesar (Best Mechanical Fit). Skills lower enemy HP by 20% right at battle start and provide a 20% chance to revive fallen troops.",
uw_auto_p_0248: "Power Armor / Robot: Bastion (+76% Bomber ATK/DEF, +280% Tactical DMG on non-multiple of 3 turns) or Phantom Cat (+76% Shooter ATK/DEF, +37.5% Lethality).",

uw_auto_h4_0249: "FORMATION 2: The Lethality Armor-Shredder",
uw_auto_p_0250: "Bypassing enemy Defense to trigger instant troop kill checks against high-HP targets.",
uw_auto_li_0251: "Bomber Choice: Alph (Equipment: +16% ATK active in Solo Combat). Skills reduce enemy Lethality by 20% and reduce enemy DEF by 20%.",
uw_auto_li_0252: "Shooter Choice: Veronica (Equipment: +16% Lethality active in Solo Attack). Skills grant +25% Lethality, +25% DEF, and a 50% chance to increase enemy damage taken by 50%.",
uw_auto_li_0253: "Shield Choice: Tyronn (Best Mechanical Fit). Skills grant +25% Lethality and increase enemy damage taken by 25%.",
uw_auto_p_0254: "Power Armor / Robot: Infercore (+65% Bomber/Shooter ATK, +60% Lethality) or Halo (+76% Bomber ATK/DEF, +30% to +80% Lethality).",

uw_auto_h4_0255: "FORMATION 3: The High-Lethality Defense Counter (Anti-Trap)",
uw_auto_p_0256: "Attacking high-Lethality defender traps safely without suffering permanent troop Losses.",
uw_auto_li_0257: "Bomber Choice: Koschevoi (Equipment: +16% DEF active in Solo Attack). Skills grant +25% flat Damage, +30% Bomber ATK, +15% Bomber DEF, and guaranteed round-by-round Tactical Damage.",
uw_auto_li_0258: "Shooter Choice: Edwin (Equipment: +16% HP active in Solo Attack). Skills cut Shieldbearer damage taken by 20% and Shooter damage taken by 30%.",
uw_auto_li_0259: "Shield Choice: Otto (Best Mechanical Fit). Skills grant up to 75% Damage Reduction and cut incoming Tactical/Basic damage.",
uw_auto_p_0260: "Power Armor / Robot: Musashimaru (+76% Shooter ATK/DEF, +30% Shield/Shooter Lethality, +45% Shield/Shooter Damage Reduction) or Atlas (+30% Army HP).",

    
