        uw_shield_heroes_title: "Shield Heroes",

    uw_shield_tyronn_name: "1. Tyronn (Scarlet Butcher)",
    uw_shield_tyronn_skill_1: "Cripple: Increases enemy Damage taken by 25%.",
    uw_shield_tyronn_skill_2: "Blood Feast: Increases allied Lethality by 25%.",
    uw_shield_tyronn_skill_3: "Death Toll: 20% chance to Stun the enemy for 1 round when attacking.",
    uw_shield_tyronn_equipment: "Exclusive Equipment (Bull Rush Lv.5): Rally attacks → Allied troops gain +16% ATK.",
    uw_shield_tyronn_synergy: "Synergy Example: Offensive frontline tank. Applying a flat +25% Damage taken debuff to enemies boosts the damage of your Shooters and Bombers simultaneously.",

    uw_shield_zoltan_name: "2. Zoltan (the Redeemer)",
    uw_shield_zoltan_skill_1: "Cycle Protection: On round numbers that are multiples of 4 (Turn 4, 8, 12...), reduces all incoming damage taken by 80%.",
    uw_shield_zoltan_skill_2: "Mecha Upgrade: Increases Shieldbearer Damage by 100%.",
    uw_shield_zoltan_skill_3: "Behemoth's Wrath: Shieldbearers retaliate after taking each basic attack, dealing 30% Tactical DMG.",
    uw_shield_zoltan_equipment: "Exclusive Equipment (Redemption Shield Lv.5): Defending → Allied troops gain +16% DEF.",
    uw_shield_zoltan_synergy: "Synergy Example: Defensive powerhouse. Retaliating with 30% Tactical DMG every time Shieldbearers take a basic hit punishes multi-hitting enemy comps.",

    uw_shield_caesar_name: "3. Caesar (Apex Ape)",
    uw_shield_caesar_skill_1: "Gene Activity: 20% chance at round end to revive soldiers lost during that round.",
    uw_shield_caesar_skill_2: "Impact Barrier: Increases allied DEF by 25%.",
    uw_shield_caesar_skill_3: "Crushing Blow: Reduces enemy troop HP by 20%.",
    uw_shield_caesar_equipment: "Exclusive Equipment (Avenger's Fury Lv.5): Defending → Allied troops gain +16% ATK.",
    uw_shield_caesar_synergy: "Synergy Example: Exceptional attrition tank. Reviving 20% of fallen troops at turn end directly counters high enemy ATK pressure.",

    uw_shield_marcus_name: "4. Marcus (Stitched Monster)",
    uw_shield_marcus_skill_1: "Monster Intimidation: On round numbers that are multiples of 2, reduces incoming basic attack damage by 50%.",
    uw_shield_marcus_skill_2: "Self-Sacrificing Battle: On round numbers that are multiples of 3, Shieldbearers skip their attack, allowing Shooters and Bombers to launch 1 extra basic attack dealing 150% DMG.",
    uw_shield_marcus_skill_3: "Death Aura: Reduces Shieldbearer damage taken by 15% and increases Bomber damage dealt by 25%.",
    uw_shield_marcus_equipment: "Exclusive Equipment (Flesh Revival Lv.5): Defending → Allied troops gain +16% HP.",
    uw_shield_marcus_synergy: "Synergy Example: The ultimate sacrifice enabler. Skipping Shieldbearer attacks on turn 3 lets your Shooters and Bombers execute devestating 150% extra basic attacks.",

    uw_shield_otto_name: "5. Otto (Tiger King)",
    uw_shield_otto_skill_1: "Natural Hymn: Odd rounds → -60% Shieldbearer Tactical DMG taken. Even rounds → -40% Shieldbearer Basic Attack DMG taken.",
    uw_shield_otto_skill_2: "Iron Protection: 83% chance each round to Shelter 1 troop type, reducing their damage taken by 75%.",
    uw_shield_otto_skill_3: "Forest Echo: Increases allied Tactical DMG by 75%.",
    uw_shield_otto_equipment: "Exclusive Equipment (Entrenched Position Lv.5): Defending → Allied troops gain +16% DEF.",
    uw_shield_otto_synergy: "Synergy Example: Massive tactical damage buffer (+75%) while providing an 83% chance to protect a random troop type with 75% mitigation every turn.",

    uw_shield_xuanming_name: "6. Xuanming (Grove Drunkard)",
    uw_shield_xuanming_skill_1: "Mountain Cleaver: Increases allied Lethality by 25%.",
    uw_shield_xuanming_skill_2: "Ironclad Protection: Increases allied DEF by 25%.",
    uw_shield_xuanming_skill_3: "Vital Surge: Reduces damage taken by 20%. If army size drops to ≤80%, recovers 10% of Lightly Wounded soldiers post-battle.",
    uw_shield_xuanming_equipment: "Exclusive Equipment (Qimen Formation Lv.2): Defending → Allied troops gain +16% ATK.",
    uw_shield_xuanming_synergy: "Synergy Example: Durable anchor providing passive DEF, Lethality, and post-battle troop recovery to minimize hospital load.",

