    "6. Power Armor / Robot Arsenal",

  uw_auto_p_0174:
    "Each march is led by 1 Power Armor. Activate Core Link nodes to unlock game-changing Exclusive Equipments.",

  uw_auto_h4_0175:
    "1. Musashimaru",

  uw_auto_p_0176:
    "Base Stats: +76% Shooter ATK / +76% Shooter DEF.",

  uw_auto_p_0177:
    "Core Link Skill (15 Nodes): Increases Shieldbearers' and Shooters' Lethality by 30% and reduces their Damage taken by 45%.",

  uw_auto_p_0178:
    "Best Pairing: Hybrid Shooter/Shield setups. Pairing Musashimaru with Edwin and Zoltan grants massive 45% damage mitigation to your front and back lines.",

  uw_auto_h4_0179:
    "2. Bastion",

  uw_auto_p_0180:
    "Base Stats: +76% Bomber ATK / +76% Bomber DEF.",

  uw_auto_p_0181:
    "Core Link Skill (15 Nodes): Increases troop DEF by 40% and Tactical DMG by 50%. On rounds that are NOT multiples of 3, Tactical DMG increases by an additional 230% (Total +280% Tactical DMG boost).",

  uw_auto_p_0182:
    "Best Pairing: Tactical Bomber comps (Wukong, Koschevoi, Lee). Deals astronomical flat damage on turns 1, 2, 4, 5, 7, 8, etc.",

  uw_auto_h4_0183:
    "3. Yokozuna",

  uw_auto_p_0184:
    "Base Stats: +76% Bomber ATK / +76% Bomber DEF.",

  uw_auto_p_0185:
    "Core Link Skill (15 Nodes): Increases troop HP by 30%. After Bombers attack 3 times, Shieldbearers take 60% less DMG and Bombers deal 30% more DMG for 2 rounds.",

  uw_auto_p_0186:
    "Best Pairing: Fast-attacking Bombers like Worrell or Ryuichi Ito.",

  uw_auto_h4_0187:
    "4. Halo",

  uw_auto_p_0188:
    "Base Stats: +76% Bomber ATK / +76% Bomber DEF.",

  uw_auto_p_0189:
    "Core Link Skill (15 Nodes): Increases troop Lethality by 30%. Every 5 attacks launched by Bombers, reduces all troop Damage taken by 25% and boosts Bomber Lethality by +50% for 2 rounds.",

  uw_auto_p_0190:
    "Best Pairing: High-Lethality Bomber marches (e.g., Whisper, Wukong). Stacks Lethality up to +80% during peak turns.",

  uw_auto_h4_0191:
    "5. Phantom Cat",

  uw_auto_p_0192:
    "Base Stats: +76% Shooter ATK / +76% Shooter DEF.",

  uw_auto_p_0193:
    "Core Link Skill (15 Nodes): Increases troop Lethality by 37.50%. Every 4 attacks launched by Shooters triggers an extra 80% Tactical DMG hit.",

  uw_auto_p_0194:
    "Best Pairing: Multi-striking Shooter comps featuring Ada or Edwin.",

  uw_auto_h4_0195:
    "6. Atlas",

  uw_auto_p_0196:
    "Base Stats: +65% Shieldbearer ATK / +65% Shieldbearer DEF.",

  uw_auto_p_0197:
    "Core Link Skill (12 Nodes): Increases all troop HP by 30%, boosts Shieldbearer Damage by 40%, and reduces Shieldbearer Damage taken from Bombers by 20%.",

  uw_auto_p_0198:
    "Best Pairing: Pure frontline defense builds.",

  uw_auto_h4_0199:
    "7. Infercore",

  uw_auto_p_0200:
    "Role: Dual DPS Lethality.",

  uw_auto_p_0201:
    "Referenced Stats: +65% Bomber/Shooter ATK / +60% Lethality.",

  uw_auto_p_0202:
    "Use: Infercore is repeatedly used in the guide's high-Lethality offensive formations and rally setups where Bomber/Shooter ATK and Lethality stacking are the main focus."

