    uw_auto_h3_0392:
  "3. 랠리 수비대 시나리오 및 단계별 실행",

uw_auto_h4_0393:
  "시나리오 1: 철의 요새 수비대 (대 거대한 높은-공격력 적 랠리)",

uw_auto_p_0394:
  "들어오는 랠리 프로필: 높은 공격력과 치명도를 집중적으로 강화한 고 전투력 적 고래 유저가 이끄는 공격적인 랠리입니다.",

uw_auto_p_0395:
  "목표: 피해 경감을 최대한 중첩하고 적 치명도를 억제하여 전열의 전투력을 유지한 채 들어오는 공격을 받아냅니다.",

uw_auto_p_0396:
  "단계 1: 수비대 대장 설정",

uw_auto_li_0397:
  "폭파범: Lanchester (장비: +16% 방어력). 수적으로 열세일 때 +25% 체력을 제공하고, 20% 기절 확률을 가지며 적 피해를 20% 감소시킵니다.",

uw_auto_li_0398:
  "실드: Otto (장비: +16% 방어력). 매 라운드마다 83% 확률로 75% 피해 감소를 제공하며, 추가로 60%/40% 피해 경감이 번갈아 적용됩니다.",

uw_auto_li_0399:
  "슈터: Kate (장비: +16% 치명도). 적 폭파범 치명도를 25%, 실드병 치명도를 20% 감소시킵니다.",

uw_auto_li_0400:
  "파워 아머 / 로봇: Musashimaru (+76% 슈터 공격력/방어력, +45% 실드/슈터 피해 감소) 또는 Atlas (+30% 부대 체력).",

uw_auto_li_0401:
  "병력 비율: 50% 실드 / 25% 폭파범 / 25% 슈터.",

uw_auto_p_0402:
  "대장 활성 장비 버프: +16% 부대 방어력 (Lanchester 장비); +16% 부대 방어력 (Otto 장비); +16% 부대 치명도 (Kate 장비); 총 대장 버프: +32% 방어력, +16% 치명도.",

uw_auto_p_0403:
  "단계 2: 4개의 합류 지원",

uw_auto_li_0404:
  "합류 1 (Alph): 스킬 1 (Photon Shield) → -20% 적 병력 치명도.",

uw_auto_li_0405:
  "합류 3 (Sawyer): 스킬 1 (Rust Erosion) → -20% 적 기본 체력.",

uw_auto_li_0406:
  "합류 3 (Lanchester): 스킬 1 (Adaptive Transformation) → +25% 부대 체력 (전투력 격차 활성).",

uw_auto_li_0407:
  "합류 4 (Caesar): 스킬 1 (Gene Activity) → 턴 종료 시 쓰러진 병력을 부활시킬 20% 확률.",

uw_auto_p_0408:
  "단계 3: 전투 실행",

uw_auto_li_0409:
  "치명도 무력화: Kate의 패시브 스킬과 Alph의 지원이 함께 작용하여 들어오는 랠리의 치명도를 최대 45% 감소시킵니다.",

uw_auto_li_0410:
  "중첩된 피해 경감: 턴 1에 Musashimaru가 실드병들과 슈터들이 받는 피해를 45% 감소시키며, Otto의 Iron Protection (83% 확률)이 75% 피해 감소를 제공합니다.",

uw_auto_li_0411:
  "체력 확장 & 부활: Lanchester의 지원이 수비대 체력을 25% 증가시킵니다. 매 라운드 종료 시 Caesar의 지원 스킬은 쓰러진 병사를 부활시킬 20% 확률을 제공합니다.",

uw_auto_p_0412:
  "결과: 들어오는 랠리의 높은 공격력이 매우 강력한 전열을 공격하지만, 공격자는 영구적인 사망을 발생시키는 데 필요한 피해 임계값에 도달하지 못합니다. 그 결과 공격자의 병원은 대규모로 채워지고, 당신의 수비대는 유지됩니다.",

uw_auto_h4_0413:
  "시나리오 2: 처형자 수비대 (대 높은-병력 / 낮은-체력 랠리)",

uw_auto_p_0414:
  "들어오는 랠리 프로필: 막대한 병력 수를 보유하지만 기본 체력과 방어 스탯이 낮은 적 랠리입니다.",

uw_auto_p_0415:
  "목표: 방어자의 이점을 활용하여 극단적인 치명도 카운터-피해로 공격하는 랠리 병력을 직접 무덤로 보냅니다.",

uw_auto_li_0416:
  "폭파범: Lee (장비: +16% 공격력). 대상이 받는 전술 피해를 50% 증가시키며 100% 공격력 전술 광역 피해를 가합니다.",

