uw_auto_h2_0294:
  "랠리 공격 종합 가이드",

uw_auto_p_0295:
  "랠리 공격은 여러 플레이어의 병력이 하나의 공격 부대로 모여 적의 도시, 요새 또는 벙커를 공격하는 연합 공격입니다.",

uw_auto_p_0296:
  "랠리 대장이 주 공격 부대를 지휘하며, 참여한 합류들은 자신의 리드 영웅의 스킬 1 효과를 제공하여 전체 랠리를 강화합니다.",

uw_auto_h3_0297:
  "1. 랠리 대장의 핵심 역할",

uw_auto_p_0298:
  "랠리 대장은 전투에 투입되는 시작 영웅과 파워 아머를 선택합니다. 따라서 전체 랠리의 초기 스탯과 전투 방향을 결정하는 가장 중요한 역할입니다.",

uw_auto_p_0299:
  "특히 랠리 대장은 전용 장비가 랠리 공격 중 발동하는 영웅을 우선적으로 선택하여 시작부터 추가적인 전체 병력 스탯 보너스를 확보해야 합니다.",

uw_auto_h3_0300:
  "2. 랠리 합류의 역할",

uw_auto_p_0301:
  "합류는 자신의 리드 영웅의 스킬 1 효과를 랠리에 제공합니다. 합류의 다른 스킬이나 편성한 영웅 전체가 랠리에 직접 적용되는 것은 아닙니다.",

uw_auto_p_0302:
  "따라서 합류 지원에서는 스킬 1의 효과와 전체 랠리에 제공하는 실제 이점을 기준으로 영웅의 우선순위를 정해야 합니다.",

uw_auto_h3_0303:
  "3. 랠리 시작 시 장비 보너스",

uw_auto_p_0304:
  "랠리 대장은 랠리 공격에서 발동하는 전용 장비를 가진 영웅을 시작 편성에 포함하는 것을 우선해야 합니다.",

uw_auto_p_0305:
  "이렇게 하면 전투 시작부터 여러 개의 전체 병력 스탯 보너스를 확보할 수 있으며, 이후 합류 지원의 스킬 1 효과와 함께 사용할 수 있습니다.",

uw_auto_h4_0306:
  "시나리오 1: 균형형 공격형 랠리",

uw_auto_p_0307:
  "목표 프로필: 다양한 병종을 포함하며 안정적인 공격 능력과 생존력을 갖춘 일반적인 적 수비대입니다.",

uw_auto_p_0308:
  "목표: 높은 공격력과 치명도를 확보하면서 적의 방어 능력을 약화시키고 안정적으로 수비대를 돌파합니다.",

uw_auto_li_0309:
  "파워 아머 / 로봇: Infercore (+65% 폭파범/슈터 공격력, +60% 치명도).",

uw_auto_li_0310:
  "실드: Tyronn (장비: +16% 공격력). 스킬 증가 적 받는 피해 에 의해 25% 및 아군 치명도 에 의해 25%.",

uw_auto_li_0311:
  "슈터: Mireya (장비: +16% 치명도). 스킬 감소 적 공격력 에 의해 20%, 증가 아군 공격력 에 의해 25%, 및 증가 아군 피해 에 의해 20%, 함께 추가 10% 할 때 적 전투력 더 낮은.",

uw_auto_li_0312:
  "합류 1 (Koschevoi): 스킬 1 (Precision Strike) → +25% 고정 부대 피해.",

uw_auto_p_0313:
  "시작 영웅 활성 장비 버프: +16% 부대 치명도 (Wukong 장비); +16% 부대 공격력 (Tyronn 장비); +16% 부대 치명도 (Mireya 장비); 총 시작 영웅 버프: +16% 공격력, +32% 치명도.",

uw_auto_h4_0314:
  "시나리오 2: 벙커-파괴자 랠리 (대응-중 실드 수비대)",

uw_auto_p_0315:
  "목표 프로필: 높은 방어력과 체력을 보유하고 있으며 실드병 방어자가 많은 강화된 적 기지입니다. 예를 들어 Zoltan 또는 Otto 방어적인 구성이 사용된 경우입니다.",

uw_auto_p_0316:
  "목표: 방어 측의 아머와 체력을 약화시켜 후방 딜러가 전방을 파괴할 수 있도록 합니다.",

uw_auto_li_0317:
  "전투 시작 (디버프 중첩): 1라운드가 시작되기 전, Sawyer의 지원이 적 기본 체력을 20% 감소시킵니다. Mireya의 Stealth Cloak이 적 공격력을 20% 감소시킵니다.",

uw_auto_li_0318:
  "실드: Tyronn (장비: +16% 공격력). 스킬 증가 적 받는 피해 에 의해 25%.",

uw_auto_li_0319:
  "피해 배율 중첩: Tyronn의 Cripple이 적이 받는 피해를 25% 증가시킵니다. Koschevoi의 지원(+25% 피해), Kate의 지원(+25% 공격력), 그리고 Mireya의 스킬이 결합되어 순수 피해량을 극한까지 끌어올립니다.",

uw_auto_li_0320:
  "파워 아머 / 로봇: Phantom Cat (+76% 슈터 공격력/방어력, +37.5% 치명도, 80% 전술 타격 매 4 슈터 공격) 또는 Bastion.",

uw_auto_p_0321:
  "목표 프로필: 높은 방어력과 체력, 다수의 실드병 방어 유닛을 활용하는 견고한 적 기지입니다 (예: Zoltan 또는 Otto 방어 구성).",

uw_auto_h4_0322:
  "시나리오 3: 높은-지속 공성 랠리 (대응-높은-치명도 함정)",

uw_auto_p_0323:
  "목표 프로필: 높은 치명도 장비와 높은 공격력을 사용하며 방어 시 Drake 또는 Kate를 사용하는 방어하는 플레이어입니다. 이 방어 플레이어는 병력 소모전을 통해 들어오는 랠리를 약화시키는 것을 목표로 합니다.",

uw_auto_p_0324:
  "목표: 랠리의 전투력을 유지하고 개별 참여자의 병력 손실을 방지하면서 지속적인 압박으로 승리합니다.",

uw_auto_li_0325:
  "슈터: Ada (장비: +16% 공격력). 스킬이 적 방어력을 10%, 체력을 15% 감소시키며, 추가 슈터 기본 공격을 발동시킵니다.",

uw_auto_li_0326:
  "파워 아머 / 로봇: Phantom Cat (+76% 슈터 공격력/방어력, +37.5% 치명도, 슈터 공격 4회마다 80% 전술 피해) 또는 Bastion.",

uw_auto_li_0327:
  "슈터: Sawyer (장비: +16% 체력). 스킬 감소 적 체력 에 의해 20% 및 증가 아군 체력 에 의해 25%.",

uw_auto_li_0328:
  "파워 아머 / 로봇: Musashimaru (+76% 슈터 공격력/방어력, +45% 피해 감소 동안 실드/슈터) 또는 Atlas (+30% 부대 체력).",

uw_auto_p_0329:
  "목표 프로필: 높은 치명도 장비와 높은 공격력을 갖추고 Drake 또는 Kate를 방어에 배치하여 들어오는 랠리를 소모전으로 무력화하도록 설계된 방어 플레이어입니다.",

uw_auto_h3_0330:
  "4. 랠리 대장 빠른-참조 표",

