    uw_auto_h3_0261:
  "3. 정찰 분석 & 카운터 선택 함께 장비 우선순위",

uw_auto_p_0262:
  "정찰 보고서를 분석할 때는 다음 결정 기준을 사용하여 영웅을 선택하세요:",

uw_auto_span_0263:
  "→ Worrell (+16% 공격력) + Edwin (+16% 체력) + Caesar",

uw_auto_span_0264:
  "→ Alph (+16% 공격력) + Veronica (+16% 치명도) + Tyronn",

uw_auto_span_0265:
  "→ Koschevoi (+16% 방어력) + Edwin (+16% 체력) + Otto",

uw_auto_h4_0266:
  "요약 의 영웅 우선순위 동안 솔로 공격",

uw_auto_li_0267:
  "먼저 장비 발동을 확정하세요: 폭파범에는 Worrell, Alph 또는 Koschevoi를, 슈터에는 Veronica 또는 Edwin을 선택하면 두 개의 +16% 장비 버프를 활성화할 수 있습니다.",

uw_auto_li_0268:
  "두 번째로 스킬을 상황에 맞게 조정하세요: 높은 순수 피해와 전술 폭발적 피해에는 Worrell/Edwin, 방어구-파괴와 높은 치명도에는 Alph/Veronica, 높은 피해의 함정에 대한 방어에는 Koschevoi/Edwin을 사용하세요.",

uw_auto_li_0269:
  "팀을 보완하는 실드 영웅을 선택하세요: 실드 영웅에는 솔로 공격 장비 발동이 없으므로 체력 감소에는 Caesar, 디버프와 치명도에는 Tyronn, 피해 감소에는 Otto를 선택하세요.",

    
    //son
    uw_auto_span_0203: "솔로 공격",
uw_auto_h2_0204: " 마스터 가이드 솔로 공격",
uw_auto_h3_0205: "1. 솔로 공격 장비 필터",
uw_auto_p_0206: "두 가지 확정적인 +16% 부대-전체 스탯 버프를 확보하려면 폭파범과 슈터를 항상 솔로 장비 목록에서 선택하도록 하세요.",

uw_auto_th_0207: "클래스",
uw_auto_th_0208: "영웅",
uw_auto_th_0209: "장비",
uw_auto_th_0210: "발동 조건",

uw_auto_td_0211: "폭파범",
uw_auto_span_0213: "Worrell",
uw_auto_td_0214: "+16% 아군 병력 공격력",
uw_auto_td_0215: "솔로 공격",

uw_auto_td_0216: "폭파범",
uw_auto_span_0218: "Alph",
uw_auto_td_0219: "+16% 아군 병력 공격력",
uw_auto_td_0220: "솔로 공격",

uw_auto_td_0221: "폭파범",
uw_auto_span_0223: "Koschevoi",
uw_auto_td_0224: "+16% 아군 병력 방어력",
uw_auto_td_0225: "솔로 공격",

uw_auto_td_0226: "슈터",
uw_auto_span_0228: "Veronica",
uw_auto_td_0229: "+16% 아군 병력 치명도",
uw_auto_td_0230: "솔로 공격",

uw_auto_td_0231: "슈터",
uw_auto_span_0233: "Edwin",
uw_auto_td_0234: "+16% 아군 병력 체력",
uw_auto_td_0235: "솔로 공격",

uw_auto_p_0236: "6명의 실드 영웅 중 솔로 공격 장비 발동을 가진 영웅은 없습니다. 모든 실드 장비 스킬은 방어 또는 랠리 공격에서 발동합니다. 따라서 솔로 공격의 실드 슬롯은 기본 스킬 시너지만을 기준으로 선택해야 합니다.",

uw_auto_h3_0237: "2. 최적화된 솔로 공격 편성 & 예시",

uw_auto_p_0238: "단계 1: 장비 필터 (선택 솔로-활성 영웅)",
uw_auto_p_0239: "폭파범 슬롯 → Worrell (+16% 공격력), Alph (+16% 공격력), 또는 Koschevoi (+16% 방어력)",
uw_auto_p_0240: "슈터 슬롯 → Veronica (+16% 치명도) 또는 Edwin (+16% 체력)",
uw_auto_p_0241: "실드 슬롯 → 최고의 기계적 보완 (예: Caesar, Otto, Tyronn)",
uw_auto_p_0242: "단계 2: 스킬 시너지 매치 대 정찰 보고서",

uw_auto_h4_0243: "편성 1: 첫-강습 전술 처형자",
uw_auto_p_0244: "높은 순수 피해, 1라운드의 즉각적인 스탯 억제, 그리고 다중 기본 공격 콤보에 집중합니다.",
uw_auto_li_0245: "폭파범 선택: Worrell (장비: 솔로 전투에서 +16% 공격력 활성). 스킬 제공 +25% 기본 공격 피해 및 a 50% 콤보 확률 동안 폭파범들.",
uw_auto_li_0246: "슈터 선택: Edwin (장비: 솔로 공격에서 +16% 체력 활성). 스킬 제공 +20% 실드병 / +30% 슈터 피해 감소 및 턴-3 전술 폭발적 피해.",
uw_auto_li_0247: "실드 선택: Caesar (최고의 기계적 적합). 전투 시작 즉시 적 체력을 20% 낮추고 쓰러진 병력을 부활시킬 20% 확률을 제공합니다.",
uw_auto_p_0248: "파워 아머 / 로봇: Bastion (+76% 폭파범 공격력/방어력, 3의 배수가 아닌 라운드에서 +280% 전술 피해) 또는 Phantom Cat (+76% 슈터 공격력/방어력, +37.5% 치명도).",

uw_auto_h4_0249: "편성 2: 치명도 아머-파쇄기",
uw_auto_p_0250: "적 방어를 우회하여 높은 체력의 목표에게 즉시 병력 처치 판정을 발생시키는 데 집중합니다.",
uw_auto_li_0251: "폭파범 선택: Alph (장비: 솔로 전투에서 +16% 공격력 활성). 스킬 감소 적 치명도 에 의해 20% 및 감소 적 방어력 에 의해 20%.",
uw_auto_li_0252: "슈터 선택: Veronica (장비: 솔로 공격에서 +16% 치명도 활성). 스킬 제공 +25% 치명도, +25% 방어력, 및 a 50% 확률 증가 적 받는 피해 에 의해 50%.",
uw_auto_li_0253: "실드 선택: Tyronn (최고의 기계적 적합). 스킬 제공 +25% 치명도 및 증가 적 받는 피해 에 의해 25%.",
uw_auto_p_0254: "파워 아머 / 로봇: Infercore (+65% 폭파범/슈터 공격력, +60% 치명도) 또는 Halo (+76% 폭파범 공격력/방어력, +30% +80% 치명도).",

uw_auto_h4_0255: "편성 3: 높은-치명도 방어 카운터 (대응-함정)",
uw_auto_p_0256: "높은 치명도의 방어자 함정을 안전하게 공격하면서 영구적인 병력 손실을 피하는 데 집중합니다.",
uw_auto_li_0257: "폭파범 선택: Koschevoi (장비: 솔로 공격에서 +16% 방어력 활성). 스킬 제공 +25% 고정 피해, +30% 폭파범 공격력, +15% 폭파범 방어력, 및 확정 라운드-에 의해-라운드 전술 피해.",
uw_auto_li_0258: "슈터 선택: Edwin (장비: 솔로 공격에서 +16% 체력 활성). 실드병이 받는 피해를 20%, 슈터가 받는 피해를 30% 감소시킵니다.",
uw_auto_li_0259: "실드 선택: Otto (최고의 기계적 적합). 최대 75% 피해 감소를 제공하고 들어오는 전술/기본 피해를 감소시킵니다.",
uw_auto_p_0260: "파워 아머 / 로봇: Musashimaru (+76% 슈터 공격력/방어력, +30% 실드/슈터 치명도, +45% 실드/슈터 피해 감소) 또는 Atlas (+30% 부대 체력).",
    
