  "單人防禦 是防守方在遊戲中擁有最強結構性優勢的戰鬥方式。當你防守自己的基地時，防禦方’s 優勢 會啟用：只要 醫院 還有可用容量，任何原本會因敵方 殺傷力 而死亡的部隊，都會自動轉換為 重度 傷兵 部隊（你的戰報中永久 損失 為 0）。",

uw_auto_p_0273:
  "與此同時，你自己的 殺傷力 對攻擊方會以 100% 完全 致命性 發揮作用，直接將對方部隊送入 墓地，成為永久 損失。",

uw_auto_h3_0274:
  "1. 三重-裝備 防禦型 篩選",

uw_auto_p_0275:
  "與 護盾 英雄 沒有 單人 裝備 觸發 的 單人 攻擊 不同，單人防禦 可以讓你同時在 全部 三種 英雄 位置 啟用 專屬裝備 (5級)。",

uw_auto_p_0276:
  "這會讓你的防守在計算 技能 或 戰力 護甲 之前，免費獲得最高 +48% 全軍-全體 屬性 的基礎加成。",

