    //sonn
    uw_auto_h3_0261:
  "3. 偵查 分析 & 反制 選擇 搭配 裝備 優先順序",

uw_auto_p_0262:
  "分析 偵查 報告 時，請使用以下決策框架來選擇你的英雄：",

uw_auto_span_0263:
  "→ Worrell (+16% 攻擊力) + Edwin (+16% 生命值) + Caesar",

uw_auto_span_0264:
  "→ Alph (+16% 攻擊力) + Veronica (+16% 殺傷力) + Tyronn",

uw_auto_span_0265:
  "→ Koschevoi (+16% 防禦力) + Edwin (+16% 生命值) + Otto",

uw_auto_h4_0266:
  "總結 的 英雄 優先順序 持續 單人 攻擊",

uw_auto_li_0267:
  "首先鎖定 裝備 觸發：爆破手 選擇 Worrell、Alph 或 Koschevoi，射手 選擇 Veronica 或 Edwin，即可確保啟用兩個 +16% 裝備 增益。",

uw_auto_li_0268:
  "其次根據情況調整 技能：使用 Worrell/Edwin 來提供原始傷害與 戰術 爆發傷害，使用 Alph/Veronica 進行 護甲-瓦解 與高 殺傷力 輸出，或使用 Koschevoi/Edwin 防禦高傷害 陷阱。",

uw_auto_li_0269:
  "選擇能與隊伍互補的 護盾 英雄：由於 護盾 英雄 沒有 單人攻擊 裝備 觸發，因此可選擇 Caesar 來降低 生命值、Tyronn 來提供 減益 與 殺傷力，或 Otto 來提供 傷害 降低。",


    
    
    
