    uw_auto_span_0203: "單人 攻擊",
uw_auto_h2_0204: " 大師 指南 單人攻擊",
uw_auto_h3_0205: "1. 單人攻擊 裝備 篩選",
uw_auto_p_0206: "請盡量從 單人 裝備 清單 中選擇 爆破手 和 射手，以確保獲得兩個 +16% 全軍-全體 屬性 增益。",

uw_auto_th_0207: "職業",
uw_auto_th_0208: "英雄",
uw_auto_th_0209: "裝備",
uw_auto_th_0210: "觸發條件",

uw_auto_td_0211: "爆破手",
uw_auto_span_0213: "Worrell",
uw_auto_td_0214: "+16% 我方 部隊 攻擊力",
uw_auto_td_0215: "單人攻擊",

uw_auto_td_0216: "爆破手",
uw_auto_span_0218: "Alph",
uw_auto_td_0219: "+16% 我方 部隊 攻擊力",
uw_auto_td_0220: "單人攻擊",

uw_auto_td_0221: "爆破手",
uw_auto_span_0223: "Koschevoi",
uw_auto_td_0224: "+16% 我方 部隊 防禦力",
uw_auto_td_0225: "單人攻擊",

uw_auto_td_0226: "射手",
uw_auto_span_0228: "Veronica",
uw_auto_td_0229: "+16% 我方 部隊 殺傷力",
uw_auto_td_0230: "單人攻擊",

uw_auto_td_0231: "射手",
uw_auto_span_0233: "Edwin",
uw_auto_td_0234: "+16% 我方 部隊 生命值",
uw_auto_td_0235: "單人攻擊",

uw_auto_p_0236: "6 名 護盾 英雄 中沒有任何英雄擁有 單人攻擊 裝備 觸發。所有 護盾 裝備 技能 都會在 防禦 或 集結攻擊 時觸發。因此在 單人 攻擊 中，護盾 位置應完全依照基礎 技能 協同效應 來選擇。",

uw_auto_h3_0237: "2. 最佳化 單人攻擊 陣型 & 範例",

uw_auto_p_0238: "步驟 1: 裝備 篩選 (選擇 單人-啟用 英雄)",
uw_auto_p_0239: "爆破手 位置 → Worrell (+16% 攻擊力)、Alph (+16% 攻擊力) 或 Koschevoi (+16% 防禦力)",
uw_auto_p_0240: "射手 位置 → Veronica (+16% 殺傷力) 或 Edwin (+16% 生命值)",
uw_auto_p_0241: "護盾 位置 → 最佳 機制上 互補（例如 Caesar、Otto、Tyronn）",
uw_auto_p_0242: "步驟 2: 技能 協同效應 對應 對 偵查 報告",

uw_auto_h4_0243: "陣型 1: 首發-打擊 戰術 處決者",
uw_auto_p_0244: "高額原始傷害、第一回合立即施加的屬性壓制，以及多段 普通攻擊 連擊。",
uw_auto_li_0245: "爆破手 選擇: Worrell（裝備: 單人戰鬥 中啟用 +16% 攻擊力）。技能 提供 +25% 普通攻擊 傷害 和 a 50% 連擊 機率 持續 爆破手.",
uw_auto_li_0246: "射手 選擇: Edwin（裝備: 單人攻擊 中啟用 +16% 生命值）。技能 提供 +20% 護盾兵 / +30% 射手 傷害 降低 和 回合-3 戰術 爆發傷害.",
uw_auto_li_0247: "護盾 選擇: Caesar（最佳 機制上 適配）。戰鬥開始時立即降低敵方 生命值 20%，並提供 20% 機率復活倒下部隊。",
uw_auto_p_0248: "動力裝甲／機器人: Bastion（+76% 爆破手 攻擊力/防禦力，非 3 的倍數回合 +280% 戰術傷害）或 Phantom Cat（+76% 射手 攻擊力/防禦力，+37.5% 殺傷力）。",

uw_auto_h4_0249: "陣型 2: 殺傷力 裝甲-粉碎者",
uw_auto_p_0250: "繞過敵方 防禦，使高 生命值 目標觸發立即 部隊 擊殺 判定。",
uw_auto_li_0251: "爆破手 選擇: Alph（裝備: 單人戰鬥 中啟用 +16% 攻擊力）。技能 降低 敵方 殺傷力 依 20% 和 降低 敵方 防禦力 依 20%。",
uw_auto_li_0252: "射手 選擇: Veronica（裝備: 單人攻擊 中啟用 +16% 殺傷力）。技能 提供 +25% 殺傷力, +25% 防禦力, 和 a 50% 機率 提高 敵方 承受傷害 依 50%。",
uw_auto_li_0253: "護盾 選擇: Tyronn（最佳 機制上 適配）。技能 提供 +25% 殺傷力 和 提高 敵方 承受傷害 依 25%。",
uw_auto_p_0254: "動力裝甲／機器人: Infercore（+65% 爆破手/射手 攻擊力、+60% 殺傷力）或 Halo（+76% 爆破手 攻擊力/防禦力、+30% 至 +80% 殺傷力）。",

uw_auto_h4_0255: "陣型 3: 高-殺傷力 防禦 反制 (反制-陷阱)",
uw_auto_p_0256: "安全攻擊高 殺傷力 的 防禦方 陷阱，同時避免永久性的 部隊 損失。",
uw_auto_li_0257: "爆破手 選擇: Koschevoi（裝備: 單人攻擊 中啟用 +16% 防禦力）。技能 提供 +25% 固定 傷害, +30% 爆破手 攻擊力, +15% 爆破手 防禦力, 和 必定 回合-依-回合 戰術傷害.",
uw_auto_li_0258: "射手 選擇: Edwin（裝備: 單人攻擊 中啟用 +16% 生命值）。護盾兵 所受 傷害 降低 20%，射手 所受 傷害 降低 30%。",
uw_auto_li_0259: "護盾 選擇: Otto（最佳 機制上 適配）。提供最高 75% 傷害減免，並降低受到的 戰術/普通 傷害。",
uw_auto_p_0260: "動力裝甲／機器人: Musashimaru（+76% 射手 攻擊力/防禦力、+30% 護盾/射手 殺傷力、+45% 護盾/射手 傷害減免）或 Atlas（+30% 全軍 生命值）。",
    
    
