uw_auto_td_0292:
  "Während Verteidigung",
    
    //son
    uw_auto_h3_0261:
  "3. Aufklärung Analyse & Konter Auswahl mit Ausrüstung Priorität",

uw_auto_p_0262:
  "Verwende bei der Auswertung eines Aufklärung Reports diesen Entscheidungsrahmen, um deine Helden auszuwählen:",

uw_auto_span_0263:
  "→ Worrell (+16% ANG) + Edwin (+16% LP) + Caesar",

uw_auto_span_0264:
  "→ Alph (+16% ANG) + Veronica (+16% Tödlichkeit) + Tyronn",

uw_auto_span_0265:
  "→ Koschevoi (+16% VERT) + Edwin (+16% LP) + Otto",

uw_auto_h4_0266:
  "Zusammenfassung von Held Priorität für Solo Angriffe",

uw_auto_li_0267:
  "Lege zuerst die Ausrüstung Auslöser fest: Wähle Worrell, Alph oder Koschevoi für den Bomber und Veronica oder Edwin für den Schütze, um zwei aktive +16% Ausrüstung Boni zu erhalten.",

uw_auto_li_0268:
  "Passe anschließend die Fähigkeiten ein: Verwende Worrell/Edwin für Rohschaden und Taktisch Burst-Schaden-Schäden, Alph/Veronica für Rüstung-Zerreißen und hohe Tödlichkeit oder Koschevoi/Edwin zur Verteidigung gegen Hoch-Schaden-Traps.",

uw_auto_li_0269:
  "Wähle den Schild Held, der das Team ergänzt: Da Schild Helden keine Solo-Angriff Ausrüstung Auslöser besitzen, wähle Caesar für LP-Reduktion, Tyronn für Debuffs und Tödlichkeit oder Otto für Schaden Reduzierung.",
    
    
    //sonn
    uw_auto_span_0203: "SOLO ANGRIFF",
uw_auto_h2_0204: "Die Meister Leitfaden zu Solo-Angriff",
uw_auto_h3_0205: "1. Die Solo-Angriff Ausrüstung Filter",
uw_auto_p_0206: "Versuche immer, deinen Bomber und Schütze aus der Solo Ausrüstung Liste auszuwählen, um zwei garantierte +16% Armee-weit Wert Boni zu erhalten.",

uw_auto_th_0207: "Klasse",
uw_auto_th_0208: "Held",
uw_auto_th_0209: "Ausrüstung",
uw_auto_th_0210: "Auslöser",

uw_auto_td_0211: "Bomber",
uw_auto_span_0213: "Worrell",
uw_auto_td_0214: "+16% Verbündete Truppe ANG",
uw_auto_td_0215: "Solo-Angriff",

uw_auto_td_0216: "Bomber",
uw_auto_span_0218: "Alph",
uw_auto_td_0219: "+16% Verbündete Truppe ANG",
uw_auto_td_0220: "Solo-Angriff",

uw_auto_td_0221: "Bomber",
uw_auto_span_0223: "Koschevoi",
uw_auto_td_0224: "+16% Verbündete Truppe VERT",
uw_auto_td_0225: "Solo-Angriff",

uw_auto_td_0226: "Schütze",
uw_auto_span_0228: "Veronica",
uw_auto_td_0229: "+16% Verbündete Truppe Tödlichkeit",
uw_auto_td_0230: "Solo-Angriff",

uw_auto_td_0231: "Schütze",
uw_auto_span_0233: "Edwin",
uw_auto_td_0234: "+16% Verbündete Truppe LP",
uw_auto_td_0235: "Solo-Angriff",

uw_auto_p_0236: "Keiner der 6 Schild Helden besitzt einen Solo-Angriff Ausrüstung Auslöser. Alle Schild Ausrüstung Fähigkeiten werden während Verteidigung oder Rally-Angriffe ausgelöst. Daher sollte der Schild-Slot bei Solo Angriffe ausschließlich anhand der grundlegenden Fähigkeit synergies gewählt werden.",

uw_auto_h3_0237: "2. Optimierte Solo-Angriff Formationen & Beispiele",

uw_auto_p_0238: "Schritt 1: Ausrüstung Filter (Auswählen Solo-Aktiv Helden)",
uw_auto_p_0239: "Bomber Slot → Worrell (+16% ANG), Alph (+16% ANG) oder Koschevoi (+16% VERT)",
uw_auto_p_0240: "Schütze Slot → Veronica (+16% Tödlichkeit) oder Edwin (+16% LP)",
uw_auto_p_0241: "Schild Slot → Beste mechanisch Ergänzung (z. B. Caesar, Otto, Tyronn)",
uw_auto_p_0242: "Schritt 2: Fähigkeit Synergie Abgleich gegen Aufklärung Bericht",

uw_auto_h4_0243: "FORMATION 1: Die Erster-Schlag Taktisch Vollstrecker",
uw_auto_p_0244: "Hoher Rohschaden, sofortige Wert-Unterdrückung in Runde 1 und Multi-Treffer-Basis-Angriff-Kombos.",
uw_auto_li_0245: "Bomber Wahl: Worrell (Ausrüstung: +16% ANG ist bei Solo-Kampf aktiv). Fähigkeiten gewähren +25% Basisangriff Schaden und a 50% Kombo Chance für Bomber.",
uw_auto_li_0246: "Schütze Wahl: Edwin (Ausrüstung: +16% LP ist bei Solo-Angriff aktiv). Fähigkeiten gewähren +20% Schildträger / +30% Schütze Schaden Reduzierung und Runde-3 Taktisch Burst-Schaden-Schäden.",
uw_auto_li_0247: "Schild Wahl: Caesar (Beste mechanisch Passform). Senkt die gegnerischen LP direkt zu Kampfbeginn um 20% und bietet eine 20% Chance, gefallene Truppen wiederzubeleben.",
uw_auto_p_0248: "Kraftrüstung / Roboter: Bastion (+76% Bomber ANG/VERT, +280% Taktischer Schaden in Runden, die keine Vielfachen von 3 sind) oder Phantom Cat (+76% Schütze ANG/VERT, +37.5% Tödlichkeit).",

uw_auto_h4_0249: "FORMATION 2: Die Tödlichkeit Rüstung-Zerteiler",
uw_auto_p_0250: "Die gegnerische Verteidigung umgehen, um gegen Ziele mit hohen LP sofortige Truppe Tötung checks auszulösen.",
uw_auto_li_0251: "Bomber Wahl: Alph (Ausrüstung: +16% ANG ist bei Solo-Kampf aktiv). Fähigkeiten verringern gegnerische Tödlichkeit um 20% und verringern gegnerische VERT um 20%.",
uw_auto_li_0252: "Schütze Wahl: Veronica (Ausrüstung: +16% Tödlichkeit ist bei Solo-Angriff aktiv). Fähigkeiten gewähren +25% Tödlichkeit, +25% VERT, und a 50% Chance zu erhöhen gegnerische erlittener Schaden um 50%.",
uw_auto_li_0253: "Schild Wahl: Tyronn (Beste mechanisch Passform). Fähigkeiten gewähren +25% Tödlichkeit und erhöhen gegnerische erlittener Schaden um 25%.",
uw_auto_p_0254: "Kraftrüstung / Roboter: Infercore (+65% Bomber/Schütze ANG, +60% Tödlichkeit) oder Halo (+76% Bomber ANG/VERT, +30% bis +80% Tödlichkeit).",

uw_auto_h4_0255: "FORMATION 3: Die Hoch-Tödlichkeit Verteidigung Konter (Anti-Falle)",
uw_auto_p_0256: "Defensiv Hoch-Tödlichkeit-Traps sicher angreifen, ohne dauerhafte Truppe Verluste zu erleiden.",
uw_auto_li_0257: "Bomber Wahl: Koschevoi (Ausrüstung: +16% VERT ist bei Solo-Angriff aktiv). Fähigkeiten gewähren +25% fest Schaden, +30% Bomber ANG, +15% Bomber VERT, und garantiert Runde-um-Runde Taktischer Schaden.",
uw_auto_li_0258: "Schütze Wahl: Edwin (Ausrüstung: +16% LP ist bei Solo-Angriff aktiv). Reduziert den von Schildträger erlittenen Schaden um 20% und den von Shootern erlittenen Schaden um 30%.",
uw_auto_li_0259: "Schild Wahl: Otto (Beste mechanisch Passform). Bietet bis zu 75% Schadensreduzierung und reduziert eingehenden Taktisch/Basis Schaden.",
uw_auto_p_0260: "Kraftrüstung / Roboter: Musashimaru (+76% Schütze ANG/VERT, +30% Schild/Schütze Tödlichkeit, +45% Schild/Schütze Schadensreduzierung) oder Atlas (+30% Armee LP).",
    
    
