    uw_shield_tyronn_skill_2: "Blood Feast: Erhöht die Tödlichkeit verbündeter Truppen um 25%.",
    uw_shield_tyronn_skill_3: "Death Toll: 20% Chance, den Gegner beim Angriff 1 Runde lang zu betäuben.",
