    uw_shield_tyronn_synergy: "Synergie Beispiel: Offensiver Frontlinie-Tank. Der pauschale Debuff von +25% erlittenem Schaden beim Gegner erhöht gleichzeitig den Schaden deiner Schütze und Bomber.",

    uw_shield_zoltan_name: "2. Zoltan (die Redeemer)",
