    uw_shield_zoltan_skill_2: "Mecha Upgrade: Erhöht den Schaden der Schildträger um 100%.",
    uw_shield_zoltan_skill_3: "Behemoth's Wrath: Schildträger führen nach jedem erhaltenen Basisangriff einen Gegenangriff aus und verursachen 30% Taktischer Schaden.",
