    uw_shield_zoltan_synergy: "Synergie Beispiel: Defensives Kraftpaket. Der Gegenangriff mit 30% Taktischer Schaden nach jedem Basis Treffer der Schildträger bestraft Gegner mit vielen Treffern.",

    uw_shield_caesar_name: "3. Caesar (Alpha-Affe)",
