    uw_shield_caesar_skill_2: "Impact Barrier: Erhöht die VERT verbündeter Truppen um 25%.",
    uw_shield_caesar_skill_3: "Crushing Blow: Reduziert die LP der gegnerischen Truppen um 20%.",
    uw_shield_caesar_equipment: "Exklusivausrüstung (Avenger's Fury Stufe 5): Verteidigung → Verbündete Truppen erhalten +16% ANG.",
    uw_shield_caesar_synergy: "Synergie Beispiel: Hervorragender Zermürbung-Tank. Die Wiederbelebung von 20% der gefallenen Truppen am Ende der Runde wirkt direkt gegen hohen gegnerischen ANG-Druck.",

    uw_shield_marcus_name: "4. Marcus (Genähtes Monster)",
