    uw_shield_marcus_skill_2: "Self-Sacrificing Battle: In Runden, deren Nummer ein Vielfaches von 3 ist, überspringen Schildträger ihren Angriff, wodurch Schütze und Bomber 1 zusätzlichen Basisangriff mit 150% Schaden ausführen können.",
    uw_shield_marcus_skill_3: "Death Aura: Reduziert den erlittenen Schaden der Schildträger um 15% und erhöht den von Bombern verursachten Schaden um 25%.",
    uw_shield_marcus_equipment: "Exklusivausrüstung (Flesh Revival Stufe 5): Verteidigung → Verbündete Truppen erhalten +16% LP.",
