    uw_auto_h3_0392:
  "3. Toplu Saldırı Garnizonu Senaryoları ve Adım Adım Uygulamalar",

uw_auto_h4_0393:
  "SENARYO 1: Demir Kale Garnizon (karşı Devasa Yüksek-Saldırı Düşman Toplu Saldırı)",

uw_auto_p_0394:
  "Gelen Toplu Saldırı Profil: Yüksek Saldırı ve Ölümcüllük üzerine yoğunlaşmış agresif bir toplu saldırı yöneten yüksek Güç seviyesine sahip bir düşman balina oyuncu.",

uw_auto_p_0395:
  "Hedef: Maksimum Hasar Azaltımı biriktirmek, düşman Ölümcüllük'yi bastırmak ve ön hat bütünlüğünü kaybetmeden gelen saldırıyı karşılamak.",

uw_auto_p_0396:
  "Adım 1: Garnizon Kumandan kurulumu",

uw_auto_li_0397:
  "Bombacı: Lanchester (Ekip.: +16% Savunma). Sayıca dezavantajlı olduğunda +25% Can sağlar, 20% Sersemletme şans verir ve düşman hasar'i 20% azaltır.",

uw_auto_li_0398:
  "Kalkan: Otto (Ekip.: +16% Savunma). Her raunt 83% şans ile 75% Hasar Azaltma sağlar ve buna ek olarak dönüşümlü 60%/40% Hasar Azaltımı uygular.",

uw_auto_li_0399:
  "Nişancı: Kate (Ekip.: +16% Ölümcüllük). Düşman Bombacı Ölümcüllük'yi 25%, Kalkan Taşıyıcı Ölümcüllük'yi 20% azaltır.",

uw_auto_li_0400:
  "Güç Zırhı / Robot: Musashimaru (+76% Nişancı Saldırı/Savunma, +45% Kalkan/Nişancı Hasar Azaltma) veya Atlas (+30% Ordu Can).",

uw_auto_li_0401:
  "Birlik Oran: 50% Kalkan / 25% Bombacı / 25% Nişancı.",

uw_auto_p_0402:
  "Kumandan Aktif Ekipman Bonusları: +16% Ordu Savunma (Lanchester Ekipman); +16% Ordu Savunma (Otto Ekipman); +16% Ordu Ölümcüllük (Kate Ekipman); Toplam Kumandan Bonuslar: +32% Savunma, +16% Ölümcüllük.",

uw_auto_p_0403:
  "Adım 2: 4 Katılımcı Desteği",

uw_auto_li_0404:
  "Katılımcı 1 (Alph): Yetenek 1 (Photon Shield) → -20% Düşman Birlik Ölümcüllük.",

uw_auto_li_0405:
  "Katılımcı 3 (Sawyer): Yetenek 1 (Rust Erosion) → -20% Düşman Temel Can.",

uw_auto_li_0406:
  "Katılımcı 3 (Lanchester): Yetenek 1 (Adaptive Transformation) → +25% Ordu Can (güç fark aktif).",

uw_auto_li_0407:
  "Katılımcı 4 (Caesar): Yetenek 1 (Gene Activity) → raunt sonunda Düşen Birlikler'u yeniden canlandırmak için 20% Şans.",

uw_auto_p_0408:
  "Adım 3: Savaş uygulaması",

uw_auto_li_0409:
  "Ölümcüllük Etkisizleştirme: Kate'in pasif yetenekler etkileri Alph'ın destek'i ile birleşerek gelen toplu saldırı'nin Ölümcüllük'sini 45%'e kadar azaltır.",

uw_auto_li_0410:
  "Katmanlı Hasar Azaltımı: Tur 1'de Musashimaru, Kalkan Taşıyıcılar ve Nişancılar'ın aldığı Hasar'i 45% azaltırken Otto'nun Iron Protection (83% şans) etkisi 75% Hasar Azaltma sağlar.",

uw_auto_li_0411:
  "Can Genişleme & Diriltme: Lanchester'ın destek'i garnizon Can'yi 25% artırır. Her raunt sonunda Caesar'ın destek yetenek'i düşen askerler'ı yeniden canlandırmak için 20% şans sağlar.",

uw_auto_p_0412:
  "Sonuç: Gelen toplu saldırı'nin yüksek Saldırı'ninı son derece dayanıklı bir ön hat'a çarpar. Saldıran taraf kalıcı ölümler oluşturmak için gereken hasar eşik'a ulaşamaz; bunun sonucunda saldıranın Hastane'ı büyük ölçüde dolar ve senin garnizon'ın sağlam kalır.",

uw_auto_h4_0413:
  "SENARYO 2: İnfazcı Garnizon (karşı Yüksek-Birlik / Düşük-Can Toplu Saldırı)",

uw_auto_p_0414:
  "Gelen Toplu Saldırı Profil: Çok yüksek birlik sayı içeren ancak temel Can ve Savunma istatistikler değerleri düşük olan bir düşman toplu saldırı.",

uw_auto_p_0415:
  "Hedef: Savunmacı Avantajı'dan yararlanarak extreme Ölümcüllük karşı hamle-hasar ile saldıran toplu saldırı birlikler'u doğrudan mezarlık'a göndermek.",

uw_auto_li_0416:
  "Bombacı: Lee (Ekip.: +16% Saldırı). Hedefin aldığı Taktik Hasarı'yi 50% artırır ve 100% Saldırı Taktik Alan hasar verir.",

uw_auto_li_0417:
  "Kalkan: Caesar (Ekip.: +16% Saldırı). Battle Start'ta düşman temel Can'yi 20% azaltır ve müttefik Savunma'i 25% artırır.",

uw_auto_li_0418:
  "Nişancı: Drake (Ekip.: +16% Ölümcüllük). +14% Saldırı, +12% Ölümcüllük ve Tur 3'te 110% Taktik Ani Hasar sağlar.",

uw_auto_li_0419:
  "Güç Zırhı / Robot: Infercore (+65% Bombacı/Nişancı Saldırı, +60% Ölümcüllük) veya Halo (+30% +80% Ölümcüllük).",

uw_auto_li_0420:
  "Birlik Oran: 25% Kalkan / 40% Bombacı / 35% Nişancı.",

uw_auto_p_0421:
  "Kumandan Aktif Ekipman Bonusları: +16% Ordu Saldırı (Lee Ekipman); +16% Ordu Saldırı (Caesar Ekipman); +16% Ordu Ölümcüllük (Drake Ekipman); Toplam Kumandan Bonuslar: +32% Saldırı, +16% Ölümcüllük.",

uw_auto_h4_0422:
  "SENARYO 3: Tur-3 Karşı Hamle-Ani Hasar Garnizon (karşı Ağır Nişancı Toplu Saldırı)",

uw_auto_p_0423:
  "Gelen Toplu Saldırı Profil: Ağır arka hat DPS kullanarak garnizon'ları hızlı şekilde kırmak üzere tasarlanmış ve 60% Nişancılar içeren bir düşman toplu saldırı.",

uw_auto_p_0424:
  "Hedef: Erken gelen Hasar'i azaltmak, Tur 2 saldırılarını karşılamak ve Tur 3'te düşman Nişancı arka hat'ını yok edecek büyük bir karşı hamle-saldırı başlatmak.",

uw_auto_li_0425:
  "Bombacı: Lee (Ekip.: +16% Saldırı). Hedefleri +50% Taktik Hasarı alınan için işaretler.",

uw_auto_li_0426:
  "Kalkan: Marcus (Ekip.: +16% Can). Çift sayılı Tur'lerde (Tur 2, 4) alınan temel saldırı hasar'i 50% azaltır. Tur 3'te Bombacılar/Nişancılar'ın 150% Hasar veren ek bir temel saldırı yapmasını sağlar.",

uw_auto_li_0427:
  "Nişancı: Kate (Ekip.: +16% Ölümcüllük). Düşman Nişancı/Bombacı etkinlik'ı azaltır ve Tur 4'ten itibaren ordu Hasar'i +43% artırır.",

uw_auto_li_0428:
  "Robot: Bastion.",

uw_auto_li_0429:
  "Birlik Oran: 30% Kalkan / 50% Bombacı / 20% Nişancı.",

uw_auto_p_0430:
  "Kumandan Aktif Ekipman Bonusları: +16% Ordu Saldırı (Lee Ekipman); +16% Ordu Can (Marcus Ekipman); +16% Ordu Ölümcüllük (Kate Ekipman); Toplam Kumandan Bonuslar: +16% Saldırı, +16% Can, +16% Ölümcüllük.",

uw_auto_li_0431:
  "Tur 1 & 2 Azaltım: Marcus'ın Monster Intimidation etkisi Tur 2'de alınan temel saldırı hasar'i 50% azaltarak 50% Bombacı yığma'inin güçlü kalmasını sağlar.",

uw_auto_li_0432:
  "Hedefleme Sinerji: Bombacılar, Nişancılar'a karşı hamle-hasar verir. 50% Bombacı yığma'in doğal hedefi düşman'nin 60% Nişancı arka hat'ıdır ve her saldırı için 20% şans ile ön hat'ı tamamen bypass eder.",

uw_auto_li_0433:
  "Tur 3 Tuzak İnfaz: Marcus Self-Sacrificing Battle'ı aktive eder. Kalkan Taşıyıcılar tur'ünü atlar ve 50% Bombacı yığma'inin 150% Hasar veren ek bir temel saldırı yapmasını sağlar. Lee, alınan tüm Taktik Hasarı'yi 50% artırır. Bastion 280% Taktik Hasarı Ani Hasar ateşler.",

uw_auto_li_0434:
  "Sonuç: Gelen Nişancı toplu saldırı, 150% güç değerindeki çift temel saldırı ile birlikte Bastion'ın 280% Taktik Ani Hasar'ünü alır. Düşman Nişancı arka hat Tur 3'te çöker.",
   
