uw_auto_span_0357:
  "TOPLU SALDIRI / GARNİZON SAVUNMA",

uw_auto_h2_0358:
  "Toplu Saldırı Garnizonu Savunma Tam Rehberi",

uw_auto_p_0359:
  "Toplu Saldırı Garnizonu Savunma, müttefik şehirleri, kaleleri ve sığınakları gelen ittifak toplu saldırı saldırılarına karşı korur. Toplu Saldırı Garnizonu'da Garnizon Kumandan savunmanın temelini oluşturur ve 3 tam kahraman yetenek seti, 1 Güç Zırhı (Robot) ve 3 aktif Savunma Ekipman (+48% toplam ordu istatistikler) sağlar.",

uw_auto_p_0360:
  "Bu sırada Garnizon'ı destekleyen ittifak üyeleri kendi birlikler birliklerini getirir ve en iyi 4 katılımcı, lider kahraman'larının yalnızca Yetenek 1'ini kullanarak tüm garnizondaki ordu'ye destek sağlar.",

uw_auto_h3_0361:
  "1. Üçlü-Ekipman Garnizon Başlangıç Filtresi",

uw_auto_p_0362:
  "Hayatta kalma ve öldürme potansiyel değerini en üst düzeye çıkarmak için Garnizon Kumandan, başlangıç Garnizon ordu'sini yalnızca Özel Ekipman (Seviye 5) özelliği Savunma sırasında tetiklenen kahraman'larla oluşturmalıdır:",

