  "SOLO SAVUNMA",

uw_auto_h2_0271:
  "Solo Savunma için Kapsamlı Rehber",

uw_auto_p_0272:
  "Solo Savunma, savunma yapan tarafın oyundaki en güçlü yapısal avantaja sahip olduğu savaş türüdür. Üssünüzü savunurken Savunmacı’s Avantaj aktif olur: Hastane'ınızda kullanılabilir kapasite olduğu sürece, düşman Ölümcüllük'si nedeniyle normalde ölecek olan birlikleriniz otomatik olarak Ağır Şekilde Yaralı birliklere dönüştürülür (raporunuzda 0 kalıcı Kayıplar).",

uw_auto_p_0273:
  "Buna karşılık, kendi Ölümcüllük'niz saldırgana karşı 100% tam ölümcüllük olarak işler ve onların birliklerini doğrudan mezarlık'a göndererek kalıcı Kayıplar oluşturur.",

