uw_auto_p_0262:
  "Bir keşif rapor'u değerlendirirken kahramanlarınızı seçmek için bu karar çerçevesini kullanın:",

uw_auto_span_0263:
  "→ Worrell (+16% Saldırı) + Edwin (+16% Can) + Caesar",

