uw_auto_h4_0266:
  "Özet Kahraman Öncelik boyunca Solo Saldırılar",

uw_auto_li_0267:
  "Öncelikle ekipman tetikleyici'larını sabitleyin: Bombacı için Worrell, Alph veya Koschevoi; Nişancı için ise Veronica veya Edwin seçmek iki adet aktif +16% ekipman bonus sağlar.",

uw_auto_li_0268:
  "İkinci olarak yetenek'leri duruma göre uyarlayın: Ham hasar ve Taktik Ani Hasar için Worrell/Edwin, zırh-parçalama ve yüksek Ölümcüllük için Alph/Veronica, yüksek hasarlı tuzak'lere karşı savunma için ise Koschevoi/Edwin kullanın.",

uw_auto_li_0269:
  "Takımı tamamlayan Kalkan kahraman'yu seçin: Kalkan kahramanlar Solo Saldırı ekipman tetikleyici'larına sahip olmadığı için Can azaltma için Caesar, debuff ve Ölümcüllük için Tyronn veya hasar azaltma için Otto seçin.",
    
    
