uw_auto_td_0234: "+16% Müttefik Birlik Can",
uw_auto_td_0235: "Solo Saldırı",

uw_auto_p_0236: "6 Kalkan Kahramanlar'ın hiçbirinde Solo Saldırı ekipman tetikleyici bulunmaz. Tüm Kalkan ekipman yetenek'leri Savunma veya Toplu Saldırılar sırasında tetiklenir. Bu nedenle Solo Saldırılar sırasında Kalkan slotunu yalnızca temel yetenek sinerjilerine göre seçmelisiniz.",

uw_auto_h3_0237: "2. Optimize Edilmiş Solo Saldırı Dizilimler & Örnekler",

uw_auto_p_0238: "Adım 1: Ekipman Filtre (Seçim Solo-Aktif Kahramanlar)",
uw_auto_p_0239: "Bombacı Slot → Worrell (+16% Saldırı), Alph (+16% Saldırı) veya Koschevoi (+16% Savunma)",
uw_auto_p_0240: "Nişancı Slot → Veronica (+16% Ölümcüllük) veya Edwin (+16% Can)",
uw_auto_p_0241: "Kalkan Slot → En İyi Mekanik Tamamlayıcı (örn. Caesar, Otto, Tyronn)",
uw_auto_p_0242: "Adım 2: Yetenek Sinerji Eşleştirme karşı Keşif Rapor",

uw_auto_h4_0243: "DİZİLİM 1: İlk-Vuruş Taktik İnfazcı",
uw_auto_p_0244: "Yüksek ham hasar, 1. turda birında istatistik baskılama ve çoklu vuruş Temel Saldırı kombinasyonlarına odaklanır.",
uw_auto_li_0245: "Bombacı Seçimi: Worrell (Ekipman: Solo Savaş sırasında +16% Saldırı aktif). Yetenekler sağlar +25% Temel Saldırı Hasar ve a 50% Kombo şans boyunca Bombacılar.",
uw_auto_li_0246: "Nişancı Seçimi: Edwin (Ekipman: Solo Saldırı sırasında +16% Can aktif). Yetenekler sağlar +20% Kalkan Taşıyıcı / +30% Nişancı hasar azaltma ve tur-3 Taktik ani hasarlar.",
uw_auto_li_0247: "Kalkan Seçimi: Caesar (En İyi Mekanik Uyum). Savaşın hemen başında düşman Can'sini %20 azaltır ve düşen birlikleri yeniden canlandırmak için %20 şans sağlar.",
uw_auto_p_0248: "Güç Zırhı / Robot: Bastion (+76% Bombacı Saldırı/Savunma, 3'ün katı olmayan turlarda +280% Taktik Hasarı) veya Phantom Cat (+76% Nişancı Saldırı/Savunma, +37.5% Ölümcüllük).",

uw_auto_h4_0249: "DİZİLİM 2: Ölümcüllük Zırh-Parçalayıcı",
uw_auto_p_0250: "Düşman Savunma'ini aşarak yüksek Can'li hedeflerde birında birlik öldürme kontrol tetiklemeye odaklanır.",
uw_auto_li_0251: "Bombacı Seçimi: Alph (Ekipman: Solo Savaş sırasında +16% Saldırı aktif). Yetenekler azaltmak düşman Ölümcüllük kadar 20% ve azaltmak düşman Savunma kadar 20%.",
uw_auto_li_0252: "Nişancı Seçimi: Veronica (Ekipman: Solo Saldırı sırasında +16% Ölümcüllük aktif). Yetenekler sağlar +25% Ölümcüllük, +25% Savunma, ve a 50% şans artırmak düşman alınan hasar kadar 50%.",
uw_auto_li_0253: "Kalkan Seçimi: Tyronn (En İyi Mekanik Uyum). Yetenekler sağlar +25% Ölümcüllük ve artırmak düşman alınan hasar kadar 25%.",
uw_auto_p_0254: "Güç Zırhı / Robot: Infercore (+65% Bombacı/Nişancı Saldırı, +60% Ölümcüllük) veya Halo (+76% Bombacı Saldırı/Savunma, +30% ila +80% Ölümcüllük).",

uw_auto_h4_0255: "DİZİLİM 3: Yüksek-Ölümcüllük Savunma Karşı Hamle (Karşı-Tuzak)",
uw_auto_p_0256: "Yüksek-Ölümcüllük savunmacı tuzak'lerine güvenli şekilde saldırırken kalıcı birlik Kayıplar yaşamamaya odaklanır.",
uw_auto_li_0257: "Bombacı Seçimi: Koschevoi (Ekipman: Solo Saldırı sırasında +16% Savunma aktif). Yetenekler sağlar +25% sabit Hasar, +30% Bombacı Saldırı, +15% Bombacı Savunma, ve garantili raunt-kadar-raunt Taktik Hasarı.",
uw_auto_li_0258: "Nişancı Seçimi: Edwin (Ekipman: Solo Saldırı sırasında +16% Can aktif). Kalkan Taşıyıcı'ın aldığı hasar'i %20, Nişancı'ın aldığı hasar'i %30 azaltır.",
uw_auto_li_0259: "Kalkan Seçimi: Otto (En İyi Mekanik Uyum). %75'e kadar Hasar Azaltma sağlar ve gelen Taktik/Temel hasar'i azaltır.",
uw_auto_p_0260: "Güç Zırhı / Robot: Musashimaru (+76% Nişancı Saldırı/Savunma, +30% Kalkan/Nişancı Ölümcüllük, +45% Kalkan/Nişancı Hasar Azaltma) veya Atlas (+30% Ordu Can).",

    
    
