/* =========================================================
   DİL DEĞİŞTİRME MEKANİZMASI
========================================================= */

function changeLanguage(lang) {
  console.log("changeLanguage çalıştı:", lang);

  // Seçilen dili kaydet
  localStorage.setItem("selectedLanguage", lang);

  // Sayfadaki tüm çevrilebilir alanları güncelle
  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const key = element.getAttribute("data-i18n");

    // Önce seçilen dildeki çeviriyi ara.
    // Yoksa İngilizce karşılığını kullan.
    const translatedText =
      translations[lang]?.[key] ??
      translations.en?.[key];

    if (translatedText !== undefined) {
      if (
        typeof translatedText === "string" &&
        translatedText.includes("<")
      ) {
        element.innerHTML = translatedText;
      } else {
        element.textContent = translatedText;
      }
    }
  });

  // Aktif dil butonunu güncelle
  document.querySelectorAll(".lang-btn").forEach((btn) => {
    if (btn.getAttribute("data-lang") === lang) {
      btn.classList.add("active");
    } else {
      btn.classList.remove("active");
    }
  });
}

