  "Sobald dein Lazarett 100% Kapazität erreicht, wird der Verteidigervorteil deaktiviert. Alle nachfolgenden tödlichen Treffer werden sofort in permanente Verluste umgewandelt.",

  uw_guide_intro:
  "Willkommen zum umfassenden Handbuch für Armeeaufstellung, Statuswechselwirkungen, Helden-Synergien und Roboter-Kraftrüstungsmechaniken. Dieser Leitfaden erklärt die Kernsysteme in einfacher Sprache und verwendet praktische Kampfbeispiele.",

