  uw_heavily_wounded_impact:
  "Wiederherstellbar durch Ressourcen und Zeit (oder Rekrutierungshalle, falls das Lazarett voll ist).",

  uw_hero_execution_order:
  "Helden handeln entsprechend ihrer Reihenfolge in deiner Formation, von links nach rechts (der Held ganz links handelt zuerst).",

  uw_hidden_kill:
  "Als Verteidiger zeigt dein Nachkampfbericht Null Verluste an, selbst wenn der Angreifer hohe Tödlichkeit gestapelt hat. Diese Tötungen werden jedoch in den Detailwerten des Angreifers als „sollten getötete Truppen sein\" erfasst, die in dein Lazarett umgeleitet wurden.",

