  "Nişancılar",

  uw_stat:
  "İstatistik",

  uw_stat_countering:
  "Bir rakip anında öldürmeleri zorlamak için büyük miktarda Ölümcüllük biriktirirse, ordunun Can ve Savunmasını artırmak infaz eşiğini yükseltir. Bu, rakibin Ölümcüllük atışının birlik kaybı kontrollerini başlatmasını engeller.",

