  uw_auto_li_0161:
  "Exclusive Equipment (Home Advantage Lv.5): Defending → Allied troops gain +16% Lethality.",

  uw_auto_p_0162:
  "Synergy Example: Anti-Lethality defender. Suppresses enemy Shield and Bomber Lethality while providing massive late-game comeback damage on turn 4.",

  uw_auto_li_0163:
  "Sweet Smile: Reduces enemy DEF by 10% and HP by 15%.",

