  uw_auto_li_0146:
  "Exklusivausrüstung (Break Out Stufe 5): Verteidigung → Verbündete Truppen erhalten +16% Tödlichkeit.",

  uw_auto_p_0147:
  "Synergie-Beispiel: Hervorragende Verteidigungs- und Burst-Einheit. Die 50%-Chance, den gegnerischen Schaden um 40% zu senken, schützt deine Frontlinie, während Runde-3-Bursts vorbereitet werden.",

  uw_auto_li_0148:
  "Rust Erosion: Verringert die gegnerischen LP um 20%.",

  uw_auto_li_0149:
  "Rage Strike: Erhöht den verbündeten Angriff um 25%.",

