  uw_auto_li_0151:
  "Exklusivausrüstung (Howling Engine Stufe 5): Rally-Angriffe → Verbündete Truppen erhalten +16% LP.",

  uw_auto_p_0152:
  "Synergie-Beispiel: Statuswert-entziehender Support-Held, der die gegnerischen LP direkt zu Kampfbeginn verringert.",

  uw_auto_li_0153:
  "Iron Body: Verringert den von Schildträgern erlittenen Schaden um 20% und den von Schützen erlittenen Schaden um 30%.",

  uw_auto_li_0154:
  "Command Shooting: Immer wenn Gegner taktischen Schaden erleiden, haben Schützen eine 30%-Chance, einen zusätzlichen Basisangriff (25% ANG) auszuführen.",

