  uw_rallyjoiners_title:
  "2. The Top 4 Joiner Assist Pool (Skill 1 Only)",

  uw_rallyjoiners_intro:
  "When alliance members send marches to your rally, you must rearrange the top 4 joiners so their Lead Heroes provide the most impactful Skill 1 assists.",

  uw_rallyjoiners_cat1_title:
  "Top Damage Buffers",

  uw_rallyjoiners_cat1_li1:
  "<strong>Koschevoi (Bomber - Skill 1: Precision Strike):</strong> Increases total Damage for all rally troops by <strong>+25%</strong>.",

