  uw_formation1_scenario_step4:
  "<strong>Taktische Verstärkung:</strong> Da Runde 1 kein Vielfaches von 3 ist, erhöht Bastion allen taktischen Schaden um 280%. Worrells doppelter Basisangriff gepaart mit Edwins defensiver Überlebensbasis zerschmilzt die gegnerische Frontlinie, bevor sie zurückschlagen kann.",

  uw_formation2_buffs:
  "<strong>Aktive Ausrüstungsboni:</strong> +16% Armee-ANG (Alph-Ausrüstung); +16% Armee-Tödlichkeit (Veronica-Ausrüstung); <strong>Gesamtboni: +16% ANG, +16% Tödlichkeit</strong>.",

