  uw_formation2_scenario_play:
  "<strong>Der Zug:</strong> Setze Alph + Veronica + Tyronn mit Infercore ein.",

  uw_formation2_scenario_steps_label:
  "<strong>Schritt-für-Schritt-Ausführung:</strong>",

  uw_formation2_scenario_step1:
  "<strong>Tödlichkeits-Stapelung:</strong> Deine Armee erhält +16% Tödlichkeit von Veronicas Ausrüstung, +25% von Veronicas Fähigkeit, +25% von Tyronns Fähigkeit und +60% von Infercore, was zu gewaltigen +126% Gesamt-Armee-Tödlichkeit führt.",

  uw_formation2_scenario_step2:
  "<strong>Rüstungs- und Schadensunterdrückung:</strong> Alphs Clever Tuning senkt die gegnerische VERT um 20%, während Tyronns Cripple den erlittenen gegnerischen Schaden um 25% erhöht.",

  uw_formation2_scenario_step3:
  "<strong>Runde-1-Ausführung:</strong> Wenn Veronica zuschlägt, erhöht ihre 50%-Chance auf Darkness Blade den erlittenen gegnerischen Schaden um weitere 50% (insgesamt +75% erlittener-Schaden-Debuff auf den Verteidiger).",

  uw_formation2_scenario_step4:
  "<strong>Ergebnis:</strong> Die extreme Tödlichkeit deiner Armee (+126%) kombiniert mit reduzierter gegnerischer Rüstung zerlegt sofort die Schildträger-Mauer des Verteidigers und verwandelt einen langen Zermürbungskampf in einen schnellen Sieg.",

  uw_formation3_buffs:
  "<strong>Aktive Ausrüstungsboni:</strong> +16% Armee-VERT (Koschevoi-Ausrüstung); +16% Armee-LP (Edwin-Ausrüstung); <strong>Gesamtboni: +16% VERT, +16% LP</strong>.",

