  "<strong>Gesamte aktive Ausrüstungsboni:</strong> +16% Armee-VERT (Lanchester-Ausrüstung); +16% Armee-VERT (Otto-Ausrüstung); +16% Armee-Tödlichkeit (Kate-Ausrüstung); <strong>Gesamter Statuswert-Boost: +32% Armee-VERT, +16% Armee-Tödlichkeit</strong>.",

