  "<strong>Tödlichkeits-Stapelung:</strong> Drake (+16% Ausrüstung, +12% Passiv) kombiniert mit Infercore (+60% für Bomber und Schützen) treibt deinen Hinterreihen-Tödlichkeitsboost auf +88%.",

  uw_archetype2_scenario_step3:
  "<strong>Runde-1-Gegenschlag:</strong> Lees Stealth Assault markiert den Gegner und erhöht dessen erlittenen taktischen Schaden um 50%. Wenn Lees Strategic Chain auslöst, trifft es alle gegnerischen Einheiten mit 100% ANG taktischem Schaden.",

  uw_archetype2_scenario_step4:
  "<strong>Angreifer-Hinrichtungs-Ausführung:</strong> Da du verteidigst, arbeitet deine +88% Tödlichkeit mit 100% Tötungseffizienz. Die LP-schwachen Einheiten des Angreifers zerschmelzen unter dem taktischen Flächenschaden, und ihr Kampfbericht zeigt massive permanente Verluste, während deine verwundeten Truppen sicher ins Lazarett umgeleitet werden.",

  uw_archetype3_title:
  "ARCHETYP 3: Die Runde-3-Gegenschlag-Falle",

  uw_archetype3_focus:
  "<strong>Hauptfokus:</strong> Frühe Runden mit starker Basisangriff-Reduzierung absorbieren, dann den Angreifer in Runde 3 mit synchronisierten Extraangriffen und taktischen Bursts auslöschen.",

  uw_archetype3_hero1:
  "<strong>Bomber:</strong> Lee (Ausr.: +16% ANG). Erhöht den vom Ziel erlittenen taktischen Schaden für 1 Runde um 50%.",

  uw_archetype3_hero2:
  "<strong>Schild:</strong> Marcus (Ausr.: +16% LP). Senkt den erlittenen Basisangriffsschaden an geraden Runden (Runde 2, 4...) um 50%. In Runde 3 setzen die Schildträger ihren Angriff aus, sodass Schützen und Bomber einen zusätzlichen Basisangriff mit 150% Schaden abfeuern können.",

  uw_archetype3_hero3:
  "<strong>Schütze:</strong> Drake (Ausr.: +16% Tödlichkeit). Feuert bei Rundenzahlen, die Vielfache von 3 sind, einen zusätzlichen taktischen Angriff mit 110% taktischem Schaden ab.",

  uw_archetype3_robot:
  "<strong>Kraftrüstung / Roboter:</strong> Bastion (+76% Bomber ANG/VERT, +40% VERT, +50% taktischer Schaden) oder Phantom Cat.",

  uw_archetype3_buffs:
  "<strong>Gesamte aktive Ausrüstungsboni:</strong> +16% Armee-ANG (Lee-Ausrüstung); +16% Armee-LP (Marcus-Ausrüstung); +16% Armee-Tödlichkeit (Drake-Ausrüstung); <strong>Gesamter Statuswert-Boost: +16% ANG, +16% LP, +16% Tödlichkeit</strong>.",

  uw_archetype3_scenario_title:
  "<strong>Szenario C: Einen aggressiven Schützen-Marsch ködern</strong>",

  uw_archetype3_scenario_attackprofile:
  "<strong>Angriffsprofil:</strong> Ein Angreifer scoutet deine Basis, sieht eine moderate Verteidigung und schickt daraufhin einen schweren Schützen-Marsch (15% Schild / 25% Bomber / 60% Schütze), um deine Mauer schnell zu durchbrechen.",

  uw_archetype3_scenario_ratio:
  "<strong>Defensives Truppenverhältnis:</strong> 30% Schild / 45% Bomber / 25% Schütze.",

  uw_archetype3_scenario_setup:
  "<strong>Der Aufbau:</strong> Setze Lee + Marcus + Drake mit Bastion ein.",

  uw_archetype3_scenario_steps_label:
  "<strong>Schritt-für-Schritt-Kampfausführung:</strong>",

  uw_archetype3_scenario_step1:
  "<strong>Runde 1 &amp; 2 (Hinhaltephase):</strong> Marcus' Monster Intimidation senkt in Runde 2 den erlittenen Basisangriffsschaden um 50% und bewahrt so die LP deiner Frontlinie.",

  uw_archetype3_scenario_step2_label:
  "<strong>Runde-3-Aktivierung (Die Falle löst aus):</strong>",

  uw_archetype3_scenario_step2a:
  "<strong>Marcus:</strong> Self-Sacrificing Battle wird aktiviert. Deine Schildträger setzen ihre Runde aus, sodass dein 45%-Bomber-Anteil und dein 25%-Schützen-Anteil einen zusätzlichen Basisangriff mit 150% Schaden abfeuern können.",

  uw_archetype3_scenario_step2b:
  "<strong>Lee:</strong> Erhöht den vom Gegner erlittenen taktischen Schaden um 50%.",

  uw_archetype3_scenario_step2c:
  "<strong>Drake:</strong> Charged Barrage löst in Runde 3 aus und feuert einen zusätzlichen taktischen Angriff mit 110% taktischem Schaden ab.",

  uw_archetype3_scenario_step3:
  "<strong>Ergebnis:</strong> In Runde 3 treffen deine Bomber und Schützen den Angreifer mit doppelten Basisangriffen bei 150% Stärke, gestapelt auf Drakes 110%-taktischem Burst. Der eingehende Angreifer-Marsch wird in einer einzigen Runde ausgelöscht.",

  uw_solodef_scoutmatrix_title:
  "3. Scout-Reaktion &amp; Verteidigungsmatrix",

  uw_solodef_scoutmatrix_intro:
  "Wenn ein eingehender Marsch oder Rally-Scout an deiner Basis erscheint, nutze diese Matrix, um deine defensive Heldenzusammenstellung und dein Truppenverhältnis zu wählen:",

