  uw_formation3_scenario_step2:
  "<strong>Tur Bazlı Azaltım:</strong> Otto'nun Iron Protection'ı her turda 83% şansla bir birlik türüne 75% Hasar Azaltımı sağlarken, Edwin gelen Nişancı hasarını 30% azaltır.",

  uw_formation3_scenario_step3:
  "<strong>Karşı Saldırı Uygulaması:</strong> Ekipman ve yetenek azaltım katmanlarıyla Can ve Savunma taban değerleriniz yükseldiğinden, savunmacının Ölümcüllük atışları Ölümcül Hasar Eşiğine ulaşamayarak başarısız olur.",

  uw_formation3_scenario_step4:
  "<strong>Sonuç:</strong> Koschevoi'nin garantili Cannon Barrage'ı (her turda ek 50% Taktik Hasar) düşman kuvvetlerini güvenle yıpratarak zaferi 0 kalıcı kayıpla garantiler.",

