  "<strong>Nişancı:</strong> Kate (Ekip: +16% Ölümcüllük). Düşman Kalkan Taşıyıcı Ölümcüllüğünü 20%, Bombacı Ölümcüllüğünü 25% azaltır. 4. turdan itibaren ordu Hasarını +43% artırır.",

  uw_archetype1_robot:
  "<strong>Güç Zırhı / Robot:</strong> Musashimaru (+76% Nişancı Saldırı/Savunma, +30% Kalkan/Nişancı Ölümcüllüğü, +45% Kalkan/Nişancı Hasar Azaltımı).",

  uw_archetype1_buffs:
  "<strong>Toplam Aktif Ekipman Bonusları:</strong> +16% Ordu Savunması (Lanchester Ekipmanı); +16% Ordu Savunması (Otto Ekipmanı); +16% Ordu Ölümcüllüğü (Kate Ekipmanı); <strong>Toplam İstatistik Artışı: +32% Ordu Savunması, +16% Ordu Ölümcüllüğü</strong>.",

  uw_archetype1_scenario_title:
  "<strong>Senaryo A: Yüksek Güçlü Bir Solo Saldırgana Karşı Savunma</strong>",

  uw_archetype1_scenario_attackprofile:
  "<strong>Saldırı Profili:</strong> Bir balina/yüksek güçlü oyuncu, yüksek Saldırı istatistiklerine sahip bir solo seferle duvarınızı zorla aşmaya çalışır.",

  uw_archetype1_scenario_ratio:
  "<strong>Savunma Birlik Oranı:</strong> 50% Kalkan / 25% Bombacı / 25% Nişancı.",

  uw_archetype1_scenario_setup:
  "<strong>Kurulum:</strong> Lanchester + Otto + Kate'i Musashimaru ile birlikte konuşlandır.",

