  "<strong>Savaş Öncesi Etkinleştirme:</strong> Lanchester, Otto ve Kate aynı anda ekipman yeteneklerini tetikleyerek üssünüze +32% Ordu Savunması ve +16% Ordu Ölümcüllüğü kazandırır.",

  uw_archetype1_scenario_step2:
  "<strong>Güç Farkı Ayarlaması:</strong> Saldırganın başlangıç gücü daha yüksek olduğundan, Lanchester'ın Adaptive Transformation'ı tetiklenerek tüm ordunuzun Canını ek olarak 25% artırır.",

  uw_archetype1_scenario_step3:
  "<strong>Ölümcüllük Etkisizleştirme:</strong> Kate'in Position Block'u saldırganın Bombacı Ölümcüllüğünü 25%, Kalkan Taşıyıcı Ölümcüllüğünü 20% baskılar.",

  uw_archetype1_scenario_step4:
  "<strong>Katmanlı Hasar Azaltımı:</strong> 1. turda Musashimaru, Kalkan Taşıyıcılarınız ve Nişancılarınızın aldığı hasarı 45% azaltır. Otto'nun Iron Protection'ı (83% şans) ön hattınıza ek olarak 75% Hasar Azaltımı uygular.",

  uw_archetype1_scenario_step5:
  "<strong>Sonuç:</strong> Saldırganın yüksek Saldırılı seferi, 80%'i aşan yığılmış hasar azaltımı ve artırılmış Can'a sahip bir duvara çarpar. Saldırı atışları öldürme kontrollerini tetikleyemez, sizin için 0 kalıcı kayıp sonucu doğar; karşı saldırılarınız ise düşman birliklerini doğrudan hastaneye gönderir.",

