  uw_auto_li_0298:
  "<strong>랠리 우선순위 제어:</strong> 랠리 대장으로서 랠리 메뉴에서 합류 목록을 수동으로 재배치하여 가장 좋은 4개의 합류 스킬 1이 활성화되도록 할 수 있습니다.",

  uw_auto_li_0306:
  "<strong>폭파범:</strong> Wukong (장비: +16% 치명도). 스킬이 3라운드마다 150%의 전술 폭발 피해를 입히고 아군 피해를 증가시킵니다.",

  uw_auto_li_0307:
  "<strong>실드:</strong> Tyronn (장비: +16% 공격력). 스킬이 적이 받는 피해를 25% 증가시키고, 치명도를 25% 증가시키며, 20% 기절 확률을 제공합니다.",

  uw_auto_li_0308:
  "<strong>슈터:</strong> Mireya (장비: +16% 치명도). 스킬이 적 공격력을 20% 감소시키고, 아군 공격력을 25% 증가시키며, 아군 피해를 최대 30%까지 증가시킵니다.",

  uw_auto_li_0313:
  "<strong>합류 2 (Sawyer):</strong> 스킬 1 (Rust Erosion) → <strong>-20% 적 기본 체력</strong>.",

  uw_auto_li_0314:
  "<strong>합류 3 (Kate):</strong> 스킬 1 (Sprint Signal) → <strong>+25% 고정 전군 공격력</strong>.",

  uw_auto_li_0315:
  "<strong>합류 4 (Xuanming):</strong> 스킬 1 (Mountain Cleaver) → <strong>+25% 고정 전군 치명도</strong>.",

  uw_auto_li_0323:
  "<strong>폭파범:</strong> Whisper (장비: +16% 치명도). 스킬이 적 방어력을 20% 감소시키고, 20% 확률로 완전한 피해 면역을 제공하며, 50% 확률로 +50% 전군 피해를 제공합니다.",

