  uw_auto_p_0300:
  "솔로 방어와 마찬가지로, 랠리 공격은 랠리 대장이 <strong>세 개의 영웅 슬롯 전체에서 동시에 전용 장비(레벨 5)를 활성화</strong>할 수 있게 합니다. 합류자를 살펴보기 전에, 랠리 대장은 반드시 이 영웅들만으로 시작 부대를 구성하여 <strong>+48%의 기본 랠리 스탯</strong>을 확보해야 합니다.",

