  uw_auto_p_0327:
  "<strong>시작 활성 장비 버프:</strong> +16% 전군 공격력 (Tyronn 장비); +16% 전군 공격력 (Ada 장비); +16% 전군 치명도 (Whisper 장비); <strong>총 시작 버프: +32% 공격력, +16% 치명도</strong>.",

