// =====================================================
// FINAL LANGUAGE APPLY
// This must be at the VERY END of lang.js
// =====================================================

document.addEventListener("DOMContentLoaded", function () {

  function applyFinalLanguage(lang) {

    console.log("FINAL LANGUAGE:", lang);

    document.querySelectorAll("[data-i18n]").forEach(function (element) {

      const key = element.getAttribute("data-i18n");

      // Önce seçilen dili kontrol et
      let text = translations[lang]?.[key];

      // Yoksa İngilizceye dön
      if (text === undefined) {
        text = translations.en?.[key];
      }

      // Hiçbir dilde yoksa HTML'deki mevcut metni bozma
      if (text === undefined) {
        return;
      }

      if (typeof text === "string" && text.includes("<")) {
        element.innerHTML = text;
      } else {
        element.textContent = text;
      }
    });

    document.querySelectorAll(".lang-btn").forEach(function (button) {

      if (button.getAttribute("data-lang") === lang) {
        button.classList.add("active");
      } else {
        button.classList.remove("active");
      }

    });
  }

  const savedLanguage =
    localStorage.getItem("selectedLanguage") || "en";

  applyFinalLanguage(savedLanguage);

});